<?php declare(strict_types=1); require __DIR__.'/../config/config.php'; $db=db(); $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){try{$db->prepare('INSERT INTO suppliers(name,phone,address) VALUES(?,?,?)')->execute([trim($_POST['name']),trim($_POST['phone']??''),trim($_POST['address']??'')]);header('Location: suppliers.php?saved=1');exit;}catch(Throwable $e){$error=$e->getMessage();}} $rows=$db->query('SELECT s.*,COALESCE((SELECT SUM(p.subtotal-p.paid) FROM purchases p WHERE p.supplier_id=s.id),0) due FROM suppliers s ORDER BY s.name')->fetchAll(); ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Suppliers</title><link rel="stylesheet" href="style.css"></head><body><header><div class="brand">💊 <?=e(APP_NAME)?></div><nav><a href="index.php">Dashboard</a><a href="pos.php">POS</a><a href="inventory.php">Inventory</a><a class="active" href="manage.php">Management</a></nav></header><main><div class="page-title"><div><div class="eyebrow">SUPPLIERS</div><h1>Suppliers</h1><p>Manage suppliers and outstanding purchase balances.</p></div></div><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><?php if(isset($_GET['saved'])):?><div class="success">✓ Supplier added.</div><?php endif;?><section class="panel"><h2>Add Supplier</h2><form method="post" class="grid"><label>Name<input name="name" required></label><label>Phone<input name="phone"></label><label>Address<input name="address"></label><button class="btn">Save Supplier</button></form></section><section class="panel"><table><tr><th>Supplier</th><th>Phone</th><th>Address</th><th>Outstanding</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['phone'])?></td><td><?=e($r['address'])?></td><td>Rs. <?=money($r['due'])?></td></tr><?php endforeach;?></table></section></main></body></html>